// ../src/cli/ci.ts
async function runCiMode(rootDir, changedFiles, base, verbose) {
  const verboseLog = verbose ? (msg) => process.stderr.write(`[ci] ${msg}
`) : NOOP_PROGRESS;
  let files;
  if (changedFiles && changedFiles.length > 0) {
    files = changedFiles;
  } else {
    const ref = base ?? "HEAD";
    try {
      const output = execFileSync2("git", ["diff", "--name-only", "--diff-filter=ACMR", ref], {
        cwd: rootDir,
        encoding: "utf-8",
        timeout: 3e4
      }).trim();
      files = output ? output.split("\n").filter(Boolean) : [];
    } catch {
      if (base === void 0) {
        files = [];
      } else {
        try {
          const output = execFileSync2("git", ["diff", "--name-only", "--diff-filter=ACMR", "HEAD"], {
            cwd: rootDir,
            encoding: "utf-8",
            timeout: 3e4
          }).trim();
          files = output ? output.split("\n").filter(Boolean) : [];
        } catch {
          files = [];
        }
      }
    }
  }
  if (files.length === 0) {
    return {
      version: 2,
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      filesAnalyzed: 0,
      missingCoChanges: [],
      chokepoints: [],
      crossCutting: [],
      flowBottlenecks: [],
      tightCouplings: [],
      hasFindings: false
    };
  }
  verboseLog(`Analyzing ${files.length} changed files`);
  const savedConfig = await loadConfig(rootDir);
  const detected = await detectContext(rootDir, verbose ? verboseLog : void 0);
  const graph = await buildGraphWithCache(rootDir, detected.language, verbose ? verboseLog : void 0);
  if (detected.secondaryLanguages) {
    for (const secLang of detected.secondaryLanguages) {
      const secGraph = await buildImportGraph(rootDir, secLang, verbose ? verboseLog : void 0);
      mergeGraph(graph, secGraph);
    }
  }
  detected.frameworks = enrichFrameworksWithUsage(detected.frameworks, graph.externalImportCounts);
  const { analysis } = await runAnalysis(
    rootDir,
    graph,
    detected,
    savedConfig,
    verbose,
    true,
    // jsonMode — suppress CLI output
    verboseLog,
    NOOP_PROGRESS
  );
  const sourceFiles = files.filter((f) => graph.centrality.has(f) || graph.inDegree.has(f));
  const nonSourceFiles = files.filter((f) => !graph.centrality.has(f) && !graph.inDegree.has(f));
  if (verbose && nonSourceFiles.length > 0) {
    verboseLog(`Skipping ${nonSourceFiles.length} non-source files: ${nonSourceFiles.slice(0, 5).join(", ")}`);
  }
  return analyzeForCI(rootDir, sourceFiles, analysis, graph);
}

// src/comment.ts
var MAX_COCHANGE_ROWS = 10;
function formatCoChangeTable(items) {
  if (items.length === 0) return "";
  const display = items.slice(0, MAX_COCHANGE_ROWS);
  const truncated = items.length > MAX_COCHANGE_ROWS;
  const rows = display.map((w) => {
    const label = w.isHiddenCoupling ? "Hidden" : "Structural";
    return `| \`${w.changed}\` | \`${w.missing}\` | ${(w.confidence * 100).toFixed(0)}% | ${label} |`;
  });
  const lines = [
    "### Missing Co-changes",
    "",
    "> These files frequently change together with files in this PR but were not included.",
    "",
    "| Changed | Usually Changes With | Confidence | Coupling |",
    "|---------|----------------------|------------|----------|",
    ...rows
  ];
  if (truncated) {
    lines.push("", `*${items.length - MAX_COCHANGE_ROWS} more not shown.*`);
  }
  return lines.join("\n");
}
var MAX_HOTSPOT_ITEMS = 10;
function formatStructuralHotspots(chokepoints, flowBottlenecks, crossCutting, collapsible) {
  const lines = [];
  for (const cp of chokepoints) {
    lines.push(
      `- :pushpin: \`${cp.file}\` is a chokepoint (${cp.separates} transitive dependents, imported by ${cp.importedBy} files)`
    );
  }
  for (const fb of flowBottlenecks) {
    lines.push(
      `- :repeat: \`${fb.file}\` is a flow bottleneck (betweenness ${fb.betweenness.toFixed(2)}, imported by ${fb.importedBy} files)`
    );
  }
  for (const cc of crossCutting) {
    lines.push(
      `- :globe_with_meridians: \`${cc.file}\` spans ${cc.layerSpread} architectural layers (${cc.layers.join(", ")})`
    );
  }
  if (lines.length === 0) return "";
  const display = lines.slice(0, MAX_HOTSPOT_ITEMS);
  if (collapsible) {
    return [
      "<details>",
      "<summary>Structural Hotspots</summary>",
      "",
      ...display,
      "",
      "</details>"
    ].join("\n");
  }
  return ["### Structural Hotspots", "", ...display].join("\n");
}
var MAX_COUPLING_ITEMS = 5;
function formatTightCoupling(items, collapsible) {
  if (items.length === 0) return "";
  const display = items.slice(0, MAX_COUPLING_ITEMS);
  const lines = display.map(
    (tc) => `- \`${tc.from}\` imports ${tc.importedNames} names from \`${tc.to}\``
  );
  if (collapsible) {
    return [
      "<details>",
      "<summary>Tight Coupling</summary>",
      "",
      ...lines,
      "",
      "</details>"
    ].join("\n");
  }
  return ["### Tight Coupling", "", ...lines].join("\n");
}
function formatComment(result) {
  if (!result.hasFindings) {
    return [
      "## Clart\xE9 Architecture Review",
      "",
      ":white_check_mark: No architectural concerns.",
      "",
      "---",
      `<sub>Powered by <a href="https://github.com/michaelabrt/clarte">Clart\xE9</a></sub>`
    ].join("\n");
  }
  const sections = ["## Clart\xE9 Architecture Review"];
  const coChangeTable = formatCoChangeTable(result.missingCoChanges);
  const hasCoChanges = coChangeTable.length > 0;
  const hotspots = formatStructuralHotspots(
    result.chokepoints,
    result.flowBottlenecks,
    result.crossCutting,
    hasCoChanges
  );
  const coupling = formatTightCoupling(result.tightCouplings, hasCoChanges);
  if (coChangeTable) sections.push("", coChangeTable);
  if (hotspots) sections.push("", hotspots);
  if (coupling) sections.push("", coupling);
  sections.push(
    "",
    "---",
    `<sub>Powered by <a href="https://github.com/michaelabrt/clarte">Clart\xE9</a></sub>`
  );
  return sections.join("\n");
}

// src/index.ts
var MARKER = "<!-- clarte-ci-review -->";
async function run2() {
  try {
    const token = core.getInput("github-token", { required: true });
    const workingDir = core.getInput("working-directory") || ".";
    const commentMode = core.getInput("comment-mode") || "update";
    const maxFiles = parseInt(core.getInput("max-files") || "50", 10);
    const verbose = core.isDebug();
    const octokit = github.getOctokit(token);
    const context2 = github.context;
    if (!context2.payload.pull_request) {
      core.info("Not a pull request event, skipping.");
      return;
    }
    const prNumber = context2.payload.pull_request.number;
    const baseSha = context2.payload.pull_request.base?.sha;
    const prFiles = await octokit.paginate(octokit.rest.pulls.listFiles, {
      ...context2.repo,
      pull_number: prNumber,
      per_page: 100
    });
    let changedFiles = prFiles.filter((f) => f.status !== "removed").map((f) => f.filename);
    if (maxFiles > 0 && changedFiles.length > maxFiles) {
      core.warning(`PR has ${changedFiles.length} changed files, analyzing first ${maxFiles}.`);
      changedFiles = changedFiles.slice(0, maxFiles);
    }
    if (changedFiles.length === 0) {
      core.info("No changed files to analyze.");
      core.setOutput("has-findings", false);
      core.setOutput("co-change-count", 0);
      return;
    }
    core.info(`Analyzing ${changedFiles.length} changed files...`);
    const result = await runCiMode(workingDir, changedFiles, baseSha, verbose);
    core.setOutput("has-findings", result.hasFindings);
    core.setOutput("co-change-count", result.missingCoChanges.length);
    core.setOutput("analysis-json", JSON.stringify(result));
    if (commentMode !== "none") {
      const commentBody = `${MARKER}
${formatComment(result)}`;
      if (commentMode === "update") {
        const { data: comments } = await octokit.rest.issues.listComments({
          ...context2.repo,
          issue_number: prNumber,
          per_page: 100
        });
        const existing = comments.find((c) => c.body?.includes(MARKER));
        if (existing) {
          const { data: updated } = await octokit.rest.issues.updateComment({
            ...context2.repo,
            comment_id: existing.id,
            body: commentBody
          });
          core.setOutput("comment-id", updated.id);
          core.info(`Updated existing comment #${updated.id}`);
        } else {
          const { data: created } = await octokit.rest.issues.createComment({
            ...context2.repo,
            issue_number: prNumber,
            body: commentBody
          });
          core.setOutput("comment-id", created.id);
          core.info(`Created comment #${created.id}`);
        }
      } else {
        const { data: created } = await octokit.rest.issues.createComment({
          ...context2.repo,
          issue_number: prNumber,
          body: commentBody
        });
        core.setOutput("comment-id", created.id);
        core.info(`Created comment #${created.id}`);
      }
    }
    core.info(
      `Findings: ${result.hasFindings ? "yes" : "none"} | ${result.missingCoChanges.length} co-change warnings | ${result.chokepoints.length} chokepoints | ${result.tightCouplings.length} tight couplings`
    );
  } catch (error) {
    core.setFailed(error instanceof Error ? error.message : String(error));
  }
}
run2();
